ExtremeValueTheory.tendstoInDistribution_hill_pareto.{u_1, u_2} {Ω : Type u_1} {Ω' : Type u_2}
  {mΩ : MeasurableSpace Ω} {mΩ' : MeasurableSpace Ω'} {P : MeasureTheory.Measure Ω}
  [MeasureTheory.IsProbabilityMeasure P] {P' : MeasureTheory.Measure Ω'}
  [MeasureTheory.IsProbabilityMeasure P'] {X : ℕ → Ω → ℝ} (hX : ∀ (i : ℕ), Measurable (X i))
  (hindep : ProbabilityTheory.iIndepFun X P)
  (hident : ∀ (i : ℕ), ProbabilityTheory.IdentDistrib (X i) (X 0) P P) {α : ℝ} (hα : 0 < α)
  (hPar : ∀ (x : ℝ), 1 ≤ x → (P {ω | x < X 0 ω}).toReal = x ^ (-α)) {k : ℕ → ℕ}
  (hk : Filter.Tendsto k Filter.atTop Filter.atTop) (hkn : ∀ᶠ (n : ℕ) in Filter.atTop, k n < n)
  {Z : Ω' → ℝ}
  (hZ : ProbabilityTheory.HasLaw Z (ProbabilityTheory.gaussianReal 0 (α⁻¹ ^ 2).toNNReal) P') :
  MeasureTheory.TendstoInDistribution
    (fun n ω => √↑(k n) * (ExtremeValueTheory.hill (fun i => X (↑i) ω) (k n) - α⁻¹)) Filter.atTop Z
    (fun x => P) P'

ExtremeValueTheory.tendstoInMeasure_pickands.{u_1} {Ω : Type u_1} [MeasurableSpace Ω]
  {P : MeasureTheory.Measure Ω} [MeasureTheory.IsProbabilityMeasure P] {X : ℕ → Ω → ℝ}
  (hX : ∀ (i : ℕ), Measurable (X i)) (hindep : ProbabilityTheory.iIndepFun X P)
  (hident : ∀ (i : ℕ), ProbabilityTheory.IdentDistrib (X i) (X 0) P P)
  {F : CumulativeDistributionFunction}
  (hF : ∀ (x : ℝ), ↑F.toStieltjesFunction x = (P {ω | X 0 ω ≤ x}).toReal) {ξ : ℝ}
  (hMDA : F.IsInMDAGEV ξ) {k : ℕ → ℕ} (hk : Filter.Tendsto k Filter.atTop Filter.atTop)
  (hkn : Filter.Tendsto (fun n => ↑(k n) / ↑n) Filter.atTop (nhds 0)) :
  MeasureTheory.TendstoInMeasure P
    (fun n ω => ExtremeValueTheory.pickands (fun i => X (↑i) ω) (k n)) Filter.atTop fun x => ξ

ExtremeValueTheory.tendstoInMeasure_momentEstimator_of_isInMDAGEV'.{u_1} {Ω : Type u_1}
  [MeasurableSpace Ω] {P : MeasureTheory.Measure Ω} [MeasureTheory.IsProbabilityMeasure P]
  {X : ℕ → Ω → ℝ} (hX : ∀ (i : ℕ), Measurable (X i)) (hindep : ProbabilityTheory.iIndepFun X P)
  (hident : ∀ (i : ℕ), ProbabilityTheory.IdentDistrib (X i) (X 0) P P)
  {F : CumulativeDistributionFunction}
  (hF : ∀ (x : ℝ), ↑F.toStieltjesFunction x = (P {ω | X 0 ω ≤ x}).toReal) {γ : ℝ}
  (hMDA : F.IsInMDAGEV γ) (hxF : ∃ y, 0 < y ∧ ↑F.toStieltjesFunction y < 1) {k : ℕ → ℕ}
  (hk : Filter.Tendsto k Filter.atTop Filter.atTop)
  (hkn : Filter.Tendsto (fun n => ↑(k n) / ↑n) Filter.atTop (nhds 0)) :
  MeasureTheory.TendstoInMeasure P
    (fun n ω => ExtremeValueTheory.momentEstimator (fun i => X (↑i) ω) (k n)) Filter.atTop fun x =>
    γ

ExtremeValueTheory.tendstoInMeasure_blockMaxEmpCDF.{u_1} {Ω : Type u_1} {mΩ : MeasurableSpace Ω}
  {P : MeasureTheory.Measure Ω} [MeasureTheory.IsProbabilityMeasure P] {X : ℕ → Ω → ℝ}
  (hX : ∀ (t : ℕ), Measurable (X t)) (hind : ProbabilityTheory.iIndepFun X P)
  (hid : ∀ (t : ℕ), ProbabilityTheory.IdentDistrib (X t) (X 0) P P) {a b : ℕ → ℝ}
  (ha : ∀ (n : ℕ), 0 < a n) {x Hx : ℝ}
  (hMDA : Filter.Tendsto (fun n => P.real {ω | X 0 ω ≤ a n * x + b n} ^ n) Filter.atTop (nhds Hx))
  {m n : ℕ → ℕ} (hm : Filter.Tendsto m Filter.atTop Filter.atTop)
  (hn : Filter.Tendsto n Filter.atTop Filter.atTop) :
  MeasureTheory.TendstoInMeasure P
    (fun k ω => ExtremeValueTheory.blockMaxEmpCDF X a b (m k) (n k) x ω) Filter.atTop fun x => Hx
